"use client";

import type { Transition } from "motion/react";
import { MotionConfig } from "motion/react";
import {
  createContext,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { cn } from "./cn";
import {
  type CadenceMode,
  type MotionOptions,
  type MotionParameterBinding,
  type MotionParameterOptions,
  type MotionTokenValues,
  type Recipe,
  type ResolvedMotionParameters,
  resolveMotionParameters,
  transitionFor,
} from "./motion";
import {
  defaultMotionScope,
  disconnectMotionTokenScope,
  type MotionScopeSnapshot,
  motionScopeStyle,
  useLocalMotionScope,
  useRootMotionScope,
} from "./motion-scope";

const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

function subscribeReducedMotion(onChange: () => void) {
  const query = window.matchMedia(REDUCED_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

/**
 * The OS preference, read in a way React can hydrate.
 *
 * Motion's own `useReducedMotion` returns the media query result on the first
 * client render, while the server can only answer `false`. That is a hydration
 * mismatch on every `data-motion` attribute in the tree, and a production build
 * does not repair it: the server's `full` stays in the DOM, so a visitor who asks
 * for reduced motion keeps the full-duration tokens — the exact failure this
 * library promises not to have. Answering `false` for the server snapshot and the
 * real value for the client snapshot makes React render twice instead of
 * mismatching.
 */
function useSystemReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    () => window.matchMedia(REDUCED_QUERY).matches,
    () => false,
  );
}

export interface CadenceMotion {
  /** The effective mode: full, reduced (system preference or prop), or none. */
  mode: CadenceMode;
  /** True when transforms and layout animations should be dropped. */
  reduced: boolean;
  /**
   * True only for `mode === "none"`. `reduced` still allows opacity and colour
   * feedback, so a CSS-driven component must check this — not `reduced` — before
   * deciding that a transition has zero duration.
   */
  disabled: boolean;
  /** Recipe/portal clock multiplier; continuous CSS loops use theme --animate-* clocks. */
  timeScale: number;
  /** Resolve a recipe into a Motion transition for the current mode. */
  transition: (recipe: Recipe, options?: MotionOptions) => Transition;
  distance: MotionTokenValues["distance"];
  spring: MotionTokenValues["spring"];
  /** Internal committed scope data; not a component migration or an executor. */
  scope: MotionScopeSnapshot;
  inheritedScope: MotionScopeSnapshot;
  parameters: (binding: MotionParameterBinding, options?: MotionParameterOptions) => ResolvedMotionParameters;
}

const CadenceContext = createContext<CadenceMotion | null>(null);

const FALLBACK_MODE: CadenceMode = "full";

function createMotion(
  mode: CadenceMode,
  timeScale = 1,
  scope = defaultMotionScope,
  inheritedScope = scope,
): CadenceMotion {
  return {
    mode,
    reduced: mode !== "full",
    disabled: mode === "none",
    timeScale,
    transition: (recipe, options) => transitionFor(recipe, mode, { timeScale, ...options }, scope),
    distance: scope.tokens.distance,
    spring: scope.tokens.spring,
    scope,
    inheritedScope,
    parameters: (binding, options) =>
      resolveMotionParameters(binding, mode, {
        timeScale,
        tokens: scope.tokens,
        effectiveDurations: scope.effectiveDurations,
        ...options,
      }),
  };
}

export interface CadenceProviderProps {
  /**
   * Motion mode for everything inside. `reduced` drops transform/layout and shortens
   * timing; `none` disables animation entirely. The system
   * `prefers-reduced-motion` setting always wins over `full`.
   *
   * Omit it to inherit the enclosing provider's mode; pass it to override the
   * enclosing scope (a preview that must show motion inside a `none` page).
   */
  mode?: CadenceMode;
  /**
   * Multiplies recipe durations, springs and portal clocks. Continuous CSS loops
   * retain the theme's --animate-* timing. `1` (default) is the authored timing;
   * the docs site passes `4` for its 0.25× preview. Additive: it does not change
   * authored tokens, so a component looks the same at `1`. Omitting it inherits the
   * enclosing scale. Finite and non-negative; zero is immediate timing, preserving mode.
   */
  timeScale?: number;
  children: ReactNode;
  className?: string;
}

/**
 * Optional provider. It wires `prefers-reduced-motion` into one `MotionConfig`
 * and exposes the resolved mode to components. Components work without it; they
 * then follow the system preference only.
 *
 * Nesting is how a subtree specialises: an inner provider inherits whatever it
 * does not set, so `<CadenceProvider timeScale={4}>` slows a region down without
 * resetting the page's mode to `full`.
 */
export function CadenceProvider({ mode, timeScale, children, className }: CadenceProviderProps) {
  const parent = useContext(CadenceContext);
  const rootScope = useRootMotionScope();
  const inheritedScope = parent?.scope ?? rootScope;
  const ref = useRef<HTMLDivElement>(null);
  const scope = useLocalMotionScope(ref, inheritedScope);
  const requested = mode ?? parent?.mode ?? FALLBACK_MODE;
  const scale = timeScale ?? parent?.timeScale ?? 1;
  const systemReduced = useSystemReducedMotion();
  if (!Number.isFinite(scale) || scale < 0) throw new RangeError("timeScale must be finite and non-negative");
  const effective: CadenceMode = requested === "none" ? "none" : systemReduced ? "reduced" : requested;
  const value = createMotion(effective, scale, scope);

  return (
    <CadenceContext.Provider value={value}>
      <MotionConfig
        reducedMotion="user"
        transition={{
          duration: scope.tokens.duration.base * scale,
          ease: scope.tokens.ease.out,
        }}
      >
        <div
          ref={ref}
          data-motion={effective}
          data-cadence-scope=""
          style={motionScopeStyle(inheritedScope, scale)}
          className={cn("contents", className)}
        >
          {children}
        </div>
      </MotionConfig>
    </CadenceContext.Provider>
  );
}

/** The resolved motion config. Falls back to the system preference when no provider is present. */
export function useCadenceMotion(ref?: RefObject<HTMLElement | SVGElement | null>): CadenceMotion {
  const context = useContext(CadenceContext);
  const root = useRootMotionScope();
  const inherited = context?.scope ?? root;
  const scope = useLocalMotionScope(ref, inherited);
  const systemReduced = useSystemReducedMotion();
  return context && !ref
    ? context
    : createMotion(
        context?.mode ?? (systemReduced ? "reduced" : FALLBACK_MODE),
        context?.timeScale ?? 1,
        scope,
        inherited,
      );
}

/** Bind a real part without replacing its caller's React 19 cleanup ref. */
export function useCadenceMotionScope<T extends HTMLElement | SVGElement>(externalRef?: Ref<T>) {
  const node = useRef<T | null>(null);
  const [, attached] = useState<T | null>(null);
  const cm = useCadenceMotion(node);
  const ref = useCallback(
    (element: T | null) => {
      if (!element) disconnectMotionTokenScope(node);
      node.current = element;
      attached(element);
      const cleanup = typeof externalRef === "function" ? externalRef(element) : undefined;
      if (externalRef && typeof externalRef !== "function") externalRef.current = element;
      return () => {
        node.current = null;
        disconnectMotionTokenScope(node);
        attached(null);
        if (typeof cleanup === "function") cleanup();
        else if (typeof externalRef === "function") externalRef(null);
        else if (externalRef) externalRef.current = null;
      };
    },
    [externalRef],
  );
  return { cm, ref };
}

/** Internal part context; keeps render children and nested portals in the owned token scope. */
export function withCadenceScope(cm: CadenceMotion, child: ReactNode) {
  return <CadenceContext.Provider value={{ ...cm, inheritedScope: cm.scope }}>{child}</CadenceContext.Provider>;
}

import type { CSSProperties } from "react";
import { cn } from "./cn";
import { duration, reducedDurationScale } from "./motion";
import { defaultMotionScope, motionScopeStyle } from "./motion-scope";
import type { CadenceMotion } from "./provider";

/** CSS variables stay local override surfaces; transport uses private fallbacks. */
export function popupClockStyle(cm: CadenceMotion): CSSProperties {
  const scope = cm.inheritedScope ?? cm.scope ?? defaultMotionScope;
  const transport = motionScopeStyle(
    { ...scope, effectiveDurations: cm.scope?.effectiveDurations ?? scope.effectiveDurations },
    cm.timeScale,
  );
  const clock = cm.disabled || cm.timeScale === 0 ? { ...transport, transition: "none" } : transport;
  if (scope.supported || !scope.ready) return clock;
  // Existing source-only consumers without the updated generated theme keep their defaults.
  const factor = (cm.disabled ? 0 : cm.reduced ? reducedDurationScale : 1) * cm.timeScale;
  return {
    ...clock,
    ...Object.fromEntries(
      Object.entries(duration).map(([key, seconds]) => [`--motion-duration-${key}`, `${seconds * factor}s`]),
    ),
  } as CSSProperties;
}

/** Evaluate Base UI state callbacks before merging; caller utilities win. */
export function stateClasses<S>(base: string, value: string | ((state: S) => string | undefined) | undefined) {
  return typeof value === "function" ? (state: S) => cn(base, value(state)) : cn(base, value);
}

/** Each portal owns its effective clock, including full inside a none scope. */
export function popupStyle(cm: CadenceMotion, value: CSSProperties | undefined): CSSProperties;
export function popupStyle<S>(
  cm: CadenceMotion,
  value: (state: S) => CSSProperties | undefined,
): (state: S) => CSSProperties;
export function popupStyle<S>(
  cm: CadenceMotion,
  value: CSSProperties | ((state: S) => CSSProperties | undefined) | undefined,
): CSSProperties | ((state: S) => CSSProperties);
export function popupStyle<S>(
  cm: CadenceMotion,
  value: CSSProperties | ((state: S) => CSSProperties | undefined) | undefined,
) {
  const clock = popupClockStyle(cm);
  const merge = (caller: CSSProperties | undefined): CSSProperties => {
    const merged = { ...clock, ...caller };
    if (cm.disabled || cm.timeScale === 0) {
      // Base UI temporarily writes the transition shorthand during popup mounting.
      // Keep that family in one shorthand instead of conflicting longhand writers.
      delete merged.transitionDuration;
      delete merged.transitionDelay;
      delete merged.transitionProperty;
      delete merged.transitionTimingFunction;
      delete merged.transitionBehavior;
      merged.transition = "none";
    }
    return merged;
  };
  return typeof value === "function" ? (state: S) => merge(value(state)) : merge(value);
}

/** Removing a native transition property cancels that running transition. */
export function popupClasses<S>(
  cm: CadenceMotion,
  base: string,
  value: string | ((state: S) => string | undefined) | undefined,
) {
  const classes = cm.disabled
    ? base
        .split(" ")
        // Suppress entry/exit fades, while preserving visibility states such as Toast limited.
        .filter((part) => !/^data-(?:\[(?:starting|ending)-style\]|(?:starting|ending)-style):opacity-0$/.test(part))
        .join(" ")
    : base;
  return stateClasses(
    cn(classes, cm.disabled ? "transition-none" : cm.reduced ? "transition-opacity" : undefined),
    value,
  );
}

"use client";

import { cancelFrame, frame, type HTMLMotionProps, motion, type Transition, useAnimationControls } from "motion/react";
import { type ComponentProps, useEffect, useLayoutEffect, useRef } from "react";

import type { CadenceMode } from "./motion";
import { type MotionEnvironment, subscribeMotionEnvironment } from "./motion-environment";
import { NativeMotionDiv } from "./native-div";

type Target = Record<string, number | string>;
const useCommittedEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function useControlAnimation(
  target: Target,
  transition: Transition,
  mode?: CadenceMode,
  onEnvironmentSettle?: () => void,
) {
  const controls = useAnimationControls();
  const current = useRef<{ target: string; mode?: CadenceMode; instant: boolean; active: boolean } | null>(null);
  const generation = useRef(0);
  const queued = useRef<(() => void) | null>(null);
  const latest = useRef(target);
  const environment = useRef<MotionEnvironment | null>(null);
  const environmentSettle = useRef(onEnvironmentSettle);
  const signature = JSON.stringify([target, transition, mode]);
  // A lifecycle owner may consume a cancelled visual internally. Never replay
  // the element's user animation-completion callback to do that bookkeeping.
  useCommittedEffect(() => {
    environmentSettle.current = onEnvironmentSettle;
  }, [onEnvironmentSettle]);
  // The signature tracks values rather than object identity. This effect's closure
  // belongs to the committed render; unrelated renders never restart the recipe.
  // signature includes every target and transition value.
  useCommittedEffect(() => {
    latest.current = target;
    const key = JSON.stringify(target);
    const instant = transition.duration === 0 || Boolean(environment.current?.hidden || environment.current?.immediate);
    const previous = current.current;
    current.current = { target: key, mode, instant, active: previous?.active ?? false };
    // Finite tweens and duration-defined springs capture their action clock.
    // Physics owners explicitly retime; restrictions always cancel, even when
    // the target is unchanged. Restoring full does not replay a settled action.
    if (
      previous?.target === key &&
      !instant &&
      !previous.instant &&
      previous.mode === mode &&
      (!transition.stiffness || !previous.active)
    )
      return;
    if (queued.current) cancelFrame(queued.current);
    const epoch = ++generation.current;
    controls.stop();
    current.current.active = false;
    const settle = () => controls.set(target);
    queued.current = settle;
    if (
      instant ||
      (previous?.target === key &&
        (previous.instant || !previous.active || (previous.mode !== mode && mode === "full")))
    ) {
      settle();
      // Motion queues same-target writes in its update phase. Reassert this
      // committed zero-clock target after older queued writes, before paint.
      frame.update(settle);
    } else {
      current.current.active = true;
      const timing = previous?.target === key && transition.stiffness ? { ...transition, delay: 0 } : transition;
      void controls.start(target, timing).then(() => {
        if (generation.current === epoch && current.current) current.current.active = false;
      });
    }
  }, [signature, controls]);
  useCommittedEffect(
    () =>
      subscribeMotionEnvironment(document, (next) => {
        environment.current = next;
        if (!next.hidden && !next.immediate) return;
        const wasActive = current.current?.active;
        if (queued.current) cancelFrame(queued.current);
        generation.current++;
        if (current.current) {
          current.current.active = false;
          current.current.instant = true;
        }
        controls.stop();
        const settle = () => controls.set(latest.current);
        queued.current = settle;
        settle();
        frame.update(settle);
        if (wasActive) environmentSettle.current?.();
      }),
    [controls],
  );
  useCommittedEffect(
    () => () => {
      if (queued.current) cancelFrame(queued.current);
      generation.current++;
      current.current = null;
      controls.stop();
    },
    [controls],
  );
  return controls;
}

type ControlSpanProps = Omit<HTMLMotionProps<"span">, "animate" | "initial" | "transition"> & {
  "data-motion"?: CadenceMode;
  target: Target;
  transition: Transition;
};
type ControlDivProps = Omit<HTMLMotionProps<"div">, "animate" | "initial" | "transition"> & {
  "data-motion"?: CadenceMode;
  target: Target;
  transition: Transition;
};

export function ControlSpan({ target, transition, ...props }: ControlSpanProps) {
  const controls = useControlAnimation(target, transition, props["data-motion"] as CadenceMode);
  return <motion.span {...props} initial={target} animate={controls} />;
}
export function ControlDiv({ target, transition, ...props }: ControlDivProps) {
  const controls = useControlAnimation(target, transition, props["data-motion"] as CadenceMode);
  return <motion.div {...props} initial={target} animate={controls} />;
}

export function NativeControlDiv({
  target,
  transition,
  ...props
}: Omit<ComponentProps<typeof NativeMotionDiv>, "animate" | "initial" | "transition"> & {
  target: Target;
  transition: Transition;
}) {
  const controls = useControlAnimation(target, transition, (props as { "data-motion"?: CadenceMode })["data-motion"]);
  return <NativeMotionDiv {...props} initial={target} animate={controls} />;
}

"use client";

import { type HTMLMotionProps, motion } from "motion/react";
import type { ComponentProps } from "react";
import { useNativeMotionRef } from "./press-button";

type NativeEvents = Pick<ComponentProps<"div">, "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd">;

function NativeDiv({
  nativeEvents,
  nativeRef,
  ref,
  ...props
}: ComponentProps<"div"> & {
  nativeEvents: NativeEvents;
  nativeRef: ComponentProps<"div">["ref"];
}) {
  const motionRef = useNativeMotionRef(ref, nativeRef);
  return <div {...props} {...nativeEvents} ref={motionRef} />;
}
const MotionNativeDiv = motion.create(NativeDiv);

type NativeKeys = "ref" | "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd";
type NativeMotionDivProps = Omit<HTMLMotionProps<"div">, NativeKeys> & Pick<ComponentProps<"div">, NativeKeys>;

export function NativeMotionDiv({
  ref,
  onAnimationStart,
  onDrag,
  onDragStart,
  onDragEnd,
  ...props
}: NativeMotionDivProps) {
  return (
    <MotionNativeDiv {...props} nativeRef={ref} nativeEvents={{ onAnimationStart, onDrag, onDragStart, onDragEnd }} />
  );
}

"use client";

import { type MotionProps, motion } from "motion/react";
import { type ComponentProps, type ReactNode, useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { useControlAnimation } from "./control-animation";
import type { CadenceMode } from "./motion";

type NativeEvents = Pick<ComponentProps<"button">, "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd">;

// Motion reserves these names. Keep native handlers outside its prop namespace,
// then restore them on the same button after Motion has resolved style and refs.
const useCommittedEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function useNativeMotionRef<T extends HTMLElement>(
  ref: import("react").Ref<T> | undefined,
  nativeRef: import("react").Ref<T> | undefined,
) {
  const node = useRef<T | null>(null);
  const motionRef = useCallback(
    (instance: T | null) => {
      node.current = instance;
      if (typeof ref === "function") return ref(instance);
      if (ref) ref.current = instance;
    },
    [ref],
  );
  // Motion 13 keeps its ref callback stable across external-ref replacement.
  // Commit the Base/caller ref separately, including React 19 cleanup ownership.
  useCommittedEffect(() => {
    const instance = node.current;
    if (!nativeRef || !instance) return;
    if (typeof nativeRef === "function") {
      const cleanup = nativeRef(instance);
      return () => {
        if (typeof cleanup === "function") cleanup();
        else nativeRef(null);
      };
    }
    nativeRef.current = instance;
    return () => {
      nativeRef.current = null;
    };
  }, [nativeRef]);
  return motionRef;
}

function NativeButton({
  nativeEvents,
  nativeRef,
  ref,
  ...props
}: ComponentProps<"button"> & {
  nativeEvents: NativeEvents;
  nativeRef: ComponentProps<"button">["ref"];
}) {
  const motionRef = useNativeMotionRef(ref, nativeRef);
  return <button {...props} {...nativeEvents} ref={motionRef} />;
}
const MotionNativeButton = motion.create(NativeButton);

export function PressButton({
  ref,
  onAnimationStart,
  onDrag,
  onDragStart,
  onDragEnd,
  whileTap,
  transition = {},
  contentOnly = false,
  decoration,
  "data-motion": mode,
  ...props
}: ComponentProps<"button"> &
  Pick<MotionProps, "whileTap" | "transition"> & {
    /** Keep the button out of a stacking context so shared decorations can pass under siblings. */
    contentOnly?: boolean;
    decoration?: ReactNode;
    "data-motion"?: string;
  }) {
  const [pressed, setPressed] = useState(false);
  const owner = useRef<number | "Enter" | null>(null);
  const release = useCallback(() => {
    owner.current = null;
    setPressed(false);
  }, []);
  const disabled = props.disabled || props["aria-disabled"] === true || props["aria-disabled"] === "true";
  const enabled = !disabled && !!whileTap;
  useCommittedEffect(() => {
    if (!pressed) return;
    const releasePointer = (event: PointerEvent) => {
      // Keyboard-generated pointercancel from another control is not this press.
      if (event.isTrusted && event.pointerId === owner.current) release();
    };
    window.addEventListener("pointerup", releasePointer);
    window.addEventListener("pointercancel", releasePointer);
    return () => {
      window.removeEventListener("pointerup", releasePointer);
      window.removeEventListener("pointercancel", releasePointer);
    };
  }, [pressed, release]);
  useCommittedEffect(() => {
    // Native disabled can swallow pointerup. Cancel this visual gesture rather
    // than reviving it when the same button is enabled again.
    if (!enabled) release();
  }, [enabled, release]);
  const pressScale = typeof whileTap === "object" && "scale" in whileTap ? whileTap.scale : 1;
  const controls = useControlAnimation(
    { scale: pressed && !disabled && typeof pressScale === "number" ? pressScale : 1 },
    disabled || !whileTap ? { duration: 0 } : transition,
    mode as CadenceMode,
  );
  return (
    <MotionNativeButton
      {...props}
      data-motion={mode}
      initial={false}
      animate={contentOnly ? undefined : controls}
      onPointerDown={(event) => {
        props.onPointerDown?.(event);
        if (enabled && event.button === 0 && event.isPrimary && owner.current === null) {
          owner.current = event.pointerId;
          setPressed(true);
        }
      }}
      onPointerUp={(event) => {
        props.onPointerUp?.(event);
        if (event.pointerId === owner.current) release();
      }}
      onPointerCancel={(event) => {
        props.onPointerCancel?.(event);
        if (event.pointerId === owner.current) release();
      }}
      onKeyDown={(event) => {
        props.onKeyDown?.(event);
        if (enabled && event.key === "Enter" && event.target === event.currentTarget && owner.current === null) {
          owner.current = "Enter";
          setPressed(true);
        }
      }}
      onKeyUp={(event) => {
        props.onKeyUp?.(event);
        if (event.key === "Enter" && owner.current === "Enter") release();
      }}
      onBlur={(event) => {
        props.onBlur?.(event);
        release();
      }}
      nativeRef={ref}
      nativeEvents={{ onAnimationStart, onDrag, onDragStart, onDragEnd }}
    >
      {decoration}
      {contentOnly ? (
        <motion.span
          data-slot="press-button-content"
          data-motion={mode}
          className="relative z-10 inline-flex items-center justify-center gap-[inherit]"
          initial={false}
          animate={controls}
        >
          {props.children}
        </motion.span>
      ) : (
        props.children
      )}
    </MotionNativeButton>
  );
}

"use client";

import type { CSSProperties, RefObject } from "react";
import { useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react";
import {
  cssEasing,
  defaultMotionTokens,
  type EffectiveMotionDurations,
  effectiveMotionTokenName,
  generatedMotionTime,
  inheritedMotionTokenName,
  isGeneratedMotionTime,
  type MotionTokenEntry,
  type MotionTokenValues,
  motionCssVersion,
  motionTokenCss,
  motionTokenEntries,
} from "./motion";

type MotionElement = HTMLElement | SVGElement;

const entries = motionTokenEntries();
const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const TOKEN_EVENT = "cadence:motion-tokens";
const probes = new WeakMap<Document, { host: HTMLElement; probe: HTMLElement }>();
const localConnections = new WeakMap<object, () => void>();

/** Ref cleanup is immediate even when a primitive detaches inside its own commit. */
export function disconnectMotionTokenScope(ref: RefObject<MotionElement | null>) {
  localConnections.get(ref)?.();
  localConnections.delete(ref);
}

function isolatedProbe(doc: Document, context: CSSStyleDeclaration, owner: MotionElement) {
  let value = probes.get(doc);
  if (!value) {
    const host = doc.createElement("span");
    host.setAttribute("data-cadence-token-probe", "");
    host.setAttribute("aria-hidden", "true");
    host.style.display = "none";
    const probe = doc.createElement("span");
    probe.style.cssText = "all:initial;display:none";
    host.attachShadow({ mode: "closed" }).appendChild(probe);
    doc.head.appendChild(host);
    value = { host, probe };
    probes.set(doc, value);
  }
  value.probe.lang = owner.closest("[lang]")?.getAttribute("lang") ?? doc.documentElement.lang;
  for (const name of [
    "font",
    ...Array.from(context).filter((name) => name.startsWith("font-")),
    "line-height",
    "writing-mode",
    "text-orientation",
    "direction",
  ])
    value.probe.style.setProperty(name, context.getPropertyValue(name));
  return value.probe;
}

export interface MotionScopeSnapshot {
  tokens: MotionTokenValues;
  effectiveDurations: EffectiveMotionDurations;
  supported: boolean;
  signature: string;
  owner: MotionElement | null;
  ready: boolean;
}

function snapshot(
  tokens: MotionTokenValues,
  effectiveDurations: EffectiveMotionDurations,
  supported: boolean,
  owner: MotionElement | null = null,
  ready = true,
): MotionScopeSnapshot {
  return {
    tokens,
    effectiveDurations,
    supported,
    owner,
    ready,
    signature: JSON.stringify([tokens, effectiveDurations, supported, ready]),
  };
}

export const defaultMotionScope = snapshot(defaultMotionTokens(), {}, false, null, false);

/** Call after a CSSOM-only edit or an application-specific non-DOM theme signal. */
export function refreshCadenceMotionTokens() {
  if (typeof document !== "undefined") document.dispatchEvent(new Event(TOKEN_EVENT));
}

/** Private fallbacks transport inputs without overriding the actual part's public CSS variables. */
export function motionScopeStyle(scope: MotionScopeSnapshot, timeScale: number): CSSProperties {
  const style: Record<string, string | number> = {
    "--cadence-time-scale": timeScale,
    "--cadence-recipe-enabled": timeScale === 0 ? 0 : 1,
  };
  if (!scope.supported) return style as CSSProperties;
  for (const entry of entries) {
    const group = scope.tokens[entry.group] as unknown as Record<
      string,
      number | readonly number[] | { visualDuration: number; bounce: number }
    >;
    const value = entry.field
      ? (group[entry.key] as { visualDuration: number; bounce: number })[entry.field]
      : group[entry.key];
    style[inheritedMotionTokenName(entry.name)] = motionTokenCss(entry, value as MotionTokenEntry["value"]);
  }
  for (const [key, value] of Object.entries(scope.effectiveDurations))
    style[effectiveMotionTokenName(key)] = generatedMotionTime(`${value}s`, 2);
  return style as CSSProperties;
}

const simpleNumber = /^[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?$/i;
const simpleUnit = /^([-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?)\s*(ms|s|px|deg)$/i;

/** Committed client read only. No rectangle reads, rendering engines or animation writers. */
export function readMotionTokenScope(element: MotionElement, inherited = defaultMotionScope): MotionScopeSnapshot {
  const view = element.ownerDocument.defaultView;
  if (!view) return inherited;
  const css = view.getComputedStyle(element);
  const supported = css.getPropertyValue("--motion-source-version").trim() === String(motionCssVersion);
  if (!supported) return snapshot(defaultMotionTokens(), {}, false, element);
  const tokens = defaultMotionTokens();
  const evaluate = (raw: string, property: "transitionDuration" | "marginLeft" | "rotate" | "flexGrow") => {
    if (raw.includes("%") || /anchor(?:-size)?\(/i.test(raw))
      throw new RangeError("Motion token units cannot depend on percentage/anchor geometry");
    const probe = isolatedProbe(element.ownerDocument, css, element);
    probe.style[property] = "";
    probe.style[property] = raw;
    if (!probe.style[property]) throw new RangeError(`Invalid motion token: ${raw}`);
    return view.getComputedStyle(probe)[property];
  };
  const numeric = (raw: string, unit: MotionTokenEntry["unit"]): number => {
    let text = raw;
    if (!simpleNumber.test(text) && !simpleUnit.test(text))
      text = evaluate(
        text,
        unit === "s" ? "transitionDuration" : unit === "px" ? "marginLeft" : unit === "deg" ? "rotate" : "flexGrow",
      );
    const match = text.match(simpleUnit);
    if (
      match &&
      (unit === "s" ? !["s", "ms"].includes(match[2]?.toLowerCase() ?? "") : match[2]?.toLowerCase() !== unit)
    )
      throw new RangeError(`Motion token has the wrong unit: ${raw}`);
    const value = match
      ? Number(match[1]) / (match[2]?.toLowerCase() === "ms" ? 1000 : 1)
      : simpleNumber.test(text)
        ? Number(text)
        : Number.NaN;
    if (!match && unit !== "number" && value !== 0) throw new RangeError(`Motion token requires ${unit}: ${raw}`);
    if (!Number.isFinite(value) || value < 0) throw new RangeError(`Invalid non-negative motion token: ${raw}`);
    return value;
  };
  {
    for (const entry of entries) {
      const raw = css.getPropertyValue(entry.name).trim();
      if (!raw) throw new RangeError(`Missing or invalid motion token: ${entry.name}`);
      if (entry.group === "ease") {
        const match = raw.match(/^cubic-bezier\(\s*([^)]*)\)$/i);
        const values = match?.[1]?.split(",").map(Number) ?? cssEasing[raw.toLowerCase()];
        if (
          values?.length !== 4 ||
          !values.every(Number.isFinite) ||
          (values[0] ?? -1) < 0 ||
          (values[0] ?? 2) > 1 ||
          (values[2] ?? -1) < 0 ||
          (values[2] ?? 2) > 1
        )
          throw new RangeError(`Motion easing must be a finite cubic-bezier: ${raw}`);
        tokens.ease[entry.key as keyof MotionTokenValues["ease"]] = values as [number, number, number, number];
      } else if (entry.group === "spring") {
        const value = numeric(raw, entry.unit);
        if (entry.field === "bounce" && value > 0.95) throw new RangeError("Motion spring bounce exceeds 0.95");
        tokens.spring[entry.key as keyof MotionTokenValues["spring"]] = {
          ...tokens.spring[entry.key as keyof MotionTokenValues["spring"]],
          [entry.field ?? "visualDuration"]: value,
        };
      } else {
        (tokens[entry.group] as Record<string, number>)[entry.key] = numeric(raw, entry.unit);
      }
    }
    const effectiveDurations = { ...inherited.effectiveDurations };
    const ancestors: MotionElement[] = [];
    // A portal's physical document ancestors must not override its logical owner.
    const transport = element.closest<HTMLElement>("[data-cadence-scope]");
    const boundary = inherited.owner
      ? inherited.owner.contains(element)
        ? inherited.owner
        : (transport ?? element).parentElement
      : null;
    for (let node: MotionElement | null = element; node && node !== boundary; node = node.parentElement)
      ancestors.push(node);
    for (const node of ancestors.reverse()) {
      const style = node === element ? css : view.getComputedStyle(node);
      for (const key of Object.keys(tokens.duration) as (keyof typeof tokens.duration)[]) {
        const raw = style.getPropertyValue(`--motion-duration-${key}`).trim();
        if (raw && (!isGeneratedMotionTime(raw) || (node !== element && /\+\s*0s\s*\*\s*2\s*\)$/.test(raw)))) {
          const literal = raw.match(/^calc\(\s*([^()*]+?)\s*(?:\*\s*[01]\s*)?\+\s*0s\s*\*\s*2\s*\)$/)?.[1]?.trim();
          effectiveDurations[key] = numeric(literal ?? raw, "s");
        }
      }
    }
    return snapshot(tokens, effectiveDurations, true, element);
  }
}

/** Only public token declarations matter; ordinary Motion/primitive style frames are ignored. */
function tokenStyle(text: string | null) {
  return (text ?? "")
    .split(";")
    .filter((declaration) =>
      /^\s*(?:--(?:motion-|ease-cadence-)[a-z0-9-]*|font(?:-[a-z-]+)?|line-height|writing-mode)\s*:/.test(declaration),
    )
    .join(";");
}

function observeScope(element: MotionElement, refresh: () => void, root = false) {
  const doc = element.ownerDocument;
  const view = doc.defaultView;
  if (!view) return () => {};
  const observer = new MutationObserver((records) => {
    if (
      records.some(
        (record) =>
          record.attributeName !== "style" ||
          tokenStyle(record.oldValue) !== tokenStyle((record.target as HTMLElement).getAttribute("style")),
      )
    )
      refresh();
  });
  for (let node: MotionElement | null = element; node; node = node.parentElement)
    observer.observe(node, {
      attributes: true,
      attributeOldValue: true,
      attributeFilter: ["class", "style", "data-motion", "data-theme", "data-color-scheme", "lang", "dir"],
    });
  const stylesheetChanged = () => doc.dispatchEvent(new Event(TOKEN_EVENT));
  const head = root
    ? new MutationObserver((records) => {
        if (
          records.some(
            (record) =>
              record.type !== "childList" ||
              [...record.addedNodes, ...record.removedNodes].some(
                (node) => !(node instanceof HTMLElement && node.hasAttribute("data-cadence-token-probe")),
              ),
          )
        )
          stylesheetChanged();
      })
    : undefined;
  head?.observe(doc.head, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["href", "media", "disabled"],
  });
  view.addEventListener("resize", refresh);
  doc.addEventListener(TOKEN_EVENT, refresh);
  if (root) doc.head.addEventListener("load", stylesheetChanged, true);
  if (root) doc.fonts?.addEventListener("loadingdone", stylesheetChanged);
  const preference = root ? view.matchMedia("(prefers-reduced-motion: reduce)") : undefined;
  preference?.addEventListener("change", refresh);
  return () => {
    observer.disconnect();
    head?.disconnect();
    view.removeEventListener("resize", refresh);
    doc.removeEventListener(TOKEN_EVENT, refresh);
    if (root) doc.head.removeEventListener("load", stylesheetChanged, true);
    if (root) doc.fonts?.removeEventListener("loadingdone", stylesheetChanged);
    preference?.removeEventListener("change", refresh);
  };
}

let rootScope = defaultMotionScope;
const rootListeners = new Set<() => void>();
let stopRoot: (() => void) | undefined;
function subscribeRoot(listener: () => void) {
  rootListeners.add(listener);
  if (!stopRoot) {
    const refresh = () => {
      const next = readMotionTokenScope(document.documentElement);
      if (next.signature !== rootScope.signature) {
        rootScope = next;
        for (const notify of rootListeners) notify();
      }
    };
    stopRoot = observeScope(document.documentElement, refresh, true);
    refresh();
  }
  return () => {
    rootListeners.delete(listener);
    if (!rootListeners.size) {
      stopRoot?.();
      stopRoot = undefined;
      probes.get(document)?.host.remove();
      probes.delete(document);
    }
  };
}

export function useRootMotionScope() {
  return useSyncExternalStore(
    subscribeRoot,
    () => rootScope,
    () => defaultMotionScope,
  );
}

function localScopeStore(initial: MotionScopeSnapshot) {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    read: () => value,
    server: () => initial,
    publish(next: MotionScopeSnapshot) {
      if (value.signature === next.signature && value.owner === next.owner) return;
      value = next;
      for (const listener of listeners) listener();
    },
  };
}

export function useLocalMotionScope(ref: RefObject<MotionElement | null> | undefined, inherited: MotionScopeSnapshot) {
  const [store] = useState(() => localScopeStore(inherited));
  const value = useSyncExternalStore(store.subscribe, store.read, store.server);
  const parent = useRef(inherited);
  const observed = useRef<{ node: MotionElement; stop: () => void } | null>(null);
  committed(() => {
    parent.current = inherited;
    const node = ref?.current;
    if (!node) {
      observed.current?.stop();
      observed.current = null;
      return;
    }
    const refresh = () => {
      const next = readMotionTokenScope(node, parent.current);
      store.publish(next);
    };
    if (observed.current?.node !== node) {
      observed.current?.stop();
      observed.current = { node, stop: observeScope(node, refresh) };
    }
    if (ref)
      localConnections.set(ref, () => {
        observed.current?.stop();
        observed.current = null;
      });
    refresh();
  });
  committed(
    () => () => {
      observed.current?.stop();
      observed.current = null;
      if (ref) localConnections.delete(ref);
    },
    [],
  );
  return ref ? value : inherited;
}

"use client";

import { type Ref, useCallback, useEffect, useInsertionEffect, useLayoutEffect, useRef, useState } from "react";
import { type CadenceMode, transitionFor } from "./motion";
import { type MotionEnvironment, subscribeMotionEnvironment } from "./motion-environment";
import { motionScopeStyle } from "./motion-scope";
import type { CadenceMotion } from "./provider";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;

type MotionElement = HTMLElement | SVGElement;

type FamilyOwner = {
  node: MotionElement;
  classes: string | null;
  applied: Record<string, string>;
  allowed: boolean;
  request?: string;
};

/** Inspect the actual connection without adding a prop to a DOM spread. */
function bindings<T>(props: T, ownership: { current: FamilyOwner | null }): T & { controller(): FamilyOwner | null } {
  return Object.defineProperty(props, "controller", { value: () => ownership.current, enumerable: false }) as T & {
    controller(): FamilyOwner | null;
  };
}

function familyStyle(text: string | null, family: "transition" | "animation") {
  return (text ?? "")
    .split(";")
    .filter((declaration) =>
      new RegExp(`^\\s*(?:${family}(?:-[a-z-]+)?${family === "animation" ? "|opacity" : ""})\\s*:`).test(declaration),
    )
    .join(";");
}

function releaseFamily(owner: FamilyOwner | null) {
  if (!owner) return;
  for (const [key, value] of Object.entries(owner.applied))
    if (owner.node.style.getPropertyValue(key) === value) owner.node.style.removeProperty(key);
  owner.applied = {};
  owner.allowed = false;
}

/** Own only an otherwise unclaimed CSS family; preserve caller declarations. */
function acquireFamily(
  node: MotionElement,
  values: Record<string, string>,
  family: "transition" | "animation",
  previous: FamilyOwner | null,
): FamilyOwner {
  const classes = node.getAttribute("class");
  const keys =
    family === "transition"
      ? [
          "transition-property",
          "transition-duration",
          "transition-delay",
          "transition-timing-function",
          "transition-behavior",
        ]
      : Array.from(node.style).filter((key) => key === "animation" || key.startsWith("animation-"));
  const intact =
    previous?.node === node &&
    previous.allowed &&
    previous.classes === classes &&
    Object.entries(previous.applied).every(([key, value]) => node.style.getPropertyValue(key) === value);
  if (!intact) {
    releaseFamily(previous);
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    const conflict =
      keys.some((key) => node.style.getPropertyValue(key) !== "") ||
      (family === "animation"
        ? css?.animationName.split(",").some((name) => name.trim() !== "" && name.trim() !== "none")
        : css?.transitionProperty !== "none" &&
          css?.transitionDuration.split(",").some((time) => parseFloat(time) > 0));
    if (conflict) return { node, classes, applied: {}, allowed: false };
  }
  const request = JSON.stringify(values);
  const probe = node.ownerDocument.createElement("span").style;
  if (!intact || previous?.request !== request)
    for (const [key, value] of Object.entries(values)) probe.setProperty(key, value);
  const canonical =
    intact && previous?.request === request
      ? previous.applied
      : Object.fromEntries(Object.keys(values).map((key) => [key, probe.getPropertyValue(key)]));
  for (const [key, value] of Object.entries(canonical))
    if (node.style.getPropertyValue(key) !== value) node.style.setProperty(key, value);
  return {
    node,
    classes,
    allowed: true,
    request,
    applied: Object.fromEntries(Object.keys(values).map((key) => [key, node.style.getPropertyValue(key)])),
  };
}

function useCssConnection<T extends MotionElement>(
  externalRef: Ref<T> | undefined,
  signature: string,
  connect: (node: T) => (release?: boolean) => void,
) {
  const node = useRef<T | null>(null);
  const [, attached] = useState<T | null>(null);
  const configuration = useRef<{ signature: string; connect(node: T): (release?: boolean) => void } | null>(null);
  const connection = useRef<{ node: T; signature: string; disconnect(release?: boolean): void } | null>(null);
  const lease = useRef<object | null>(null);
  const reconcile = () => {
    const config = configuration.current;
    if (connection.current?.node === node.current && connection.current?.signature === config?.signature) return;
    connection.current?.disconnect(false);
    connection.current =
      node.current && config
        ? { node: node.current, signature: config.signature, disconnect: config.connect(node.current) }
        : null;
  };
  committed(() => {
    configuration.current = { signature, connect };
    reconcile();
  });
  committed(
    () => () => {
      connection.current?.disconnect();
      connection.current = null;
    },
    [],
  );
  const ref = useCallback(
    (element: T | null) => {
      const identity = {};
      lease.current = identity;
      connection.current?.disconnect();
      connection.current = null;
      node.current = element;
      attached(element);
      const cleanup = typeof externalRef === "function" ? externalRef(element) : undefined;
      if (externalRef && typeof externalRef !== "function") externalRef.current = element;
      const config = configuration.current;
      if (element && config)
        connection.current = { node: element, signature: config.signature, disconnect: config.connect(element) };
      return () => {
        if (lease.current === identity) {
          connection.current?.disconnect();
          connection.current = null;
          node.current = null;
          attached(null);
        }
        if (typeof cleanup === "function") cleanup();
        else if (typeof externalRef === "function") externalRef(null);
        else if (externalRef && externalRef.current === element) externalRef.current = null;
      };
    },
    [externalRef],
  );
  return { ref, node };
}
export const colorProperties = [
  "background-color",
  "color",
  "border-top-color",
  "border-right-color",
  "border-bottom-color",
  "border-left-color",
  "fill",
  "stroke",
  "text-decoration-color",
  "box-shadow",
  "text-shadow",
] as const;
export type ColorProperty = (typeof colorProperties)[number];

function properties(values: readonly ColorProperty[]) {
  if (!values.length || new Set(values).size !== values.length || values.some((p) => !colorProperties.includes(p)))
    throw new RangeError("state.color requires unique explicit colour properties");
  return values.join(", ");
}

// CSSOM keyframes resolve colour functions. Unknown syntax/topology is immediate.
function shadowShape(value: unknown) {
  if (typeof value !== "string" || value === "none") return null;
  const shape = value.replace(/(?:rgba?|hsla?|oklab|oklch|lab|lch|color)\([^)]*\)/gi, "").trim();
  return /^(?:inset|[\d\s.,+\-px])+$/i.test(shape) ? shape.replace(/\s+/g, " ") : null;
}

function cancelUnsafeShadows(node: MotionElement, owned: readonly ColorProperty[]) {
  for (const animation of node.getAnimations?.() ?? []) {
    const effect = animation.effect as KeyframeEffect | null;
    if (!("transitionProperty" in animation) || effect?.target !== node || effect.pseudoElement) continue;
    const property = String(animation.transitionProperty);
    if (!owned.includes(property as ColorProperty) || !property.endsWith("shadow")) continue;
    const frames = (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
    const key = property === "box-shadow" ? "boxShadow" : "textShadow";
    const shapes = frames.map((frame) => shadowShape(frame[key]));
    if (!shapes.length || shapes.some((shape) => shape === null || shape !== shapes[0])) animation.cancel();
  }
}

function cancelColors(node: MotionElement, owned: readonly ColorProperty[]) {
  for (const animation of node.getAnimations?.() ?? []) {
    const effect = animation.effect as KeyframeEffect | null;
    if (
      "transitionProperty" in animation &&
      effect?.target === node &&
      !effect.pseudoElement &&
      owned.includes(String(animation.transitionProperty) as ColorProperty)
    )
      animation.cancel();
  }
}

/** One explicit CSS colour owner. It never samples/pins colour targets inline. */
export function useStateColor<T extends MotionElement>(
  externalRef: Ref<T> | undefined,
  cm: CadenceMotion,
  owned: readonly ColorProperty[],
  options: { immediate?: boolean; readability?: "verified" | "immediate" } = {},
) {
  const previousMode = useRef<CadenceMode>(cm.mode);
  const ownership = useRef<FamilyOwner | null>(null);
  const environmentRef = useRef<MotionEnvironment | null>(null);
  const property = properties(owned);
  const immediate =
    options.immediate ||
    options.readability === "immediate" ||
    (options.readability !== "verified" && owned.some((p) => p === "color" || p === "background-color"));
  const signature = JSON.stringify([property, cm.mode, cm.timeScale, options, cm.scope.signature]);
  // Update an existing owner's clock before any layout effect samples a newly
  // committed state. No computed-style/layout reads or new ownership here.
  useInsertionEffect(() => {
    const record = ownership.current;
    if (!record?.allowed) return;
    if (Object.entries(record.applied).some(([key, value]) => record.node.style.getPropertyValue(key) !== value)) {
      releaseFamily(record);
      return;
    }
    const node = record.node;
    const env = environmentRef.current;
    const suppress =
      immediate ||
      node === node.ownerDocument.activeElement ||
      node.contains(node.ownerDocument.activeElement) ||
      node.matches('[aria-invalid="true"], [data-invalid]:not([data-invalid="false"])') ||
      env?.hidden ||
      env?.immediate ||
      env?.themeOwned;
    const seconds = suppress ? 0 : (cm.transition("state.color").duration ?? 0);
    if (node.style.getPropertyValue("transition-duration") !== `${seconds}s`)
      node.style.setProperty("transition-duration", `${seconds}s`);
    record.applied["transition-duration"] = node.style.getPropertyValue("transition-duration");
  });
  const owner = useCssConnection(externalRef, signature, (node) => {
    let environment: MotionEnvironment;
    let focus = node === node.ownerDocument.activeElement || node.contains(node.ownerDocument.activeElement);
    const update = (env: MotionEnvironment) => {
      environment = env;
      environmentRef.current = env;
      const mode: CadenceMode = cm.disabled ? "none" : env.reduced ? "reduced" : cm.mode;
      const clock = transitionFor("state.color", mode, { timeScale: cm.timeScale }, cm.scope);
      const invalid = node.matches('[aria-invalid="true"], [data-invalid]:not([data-invalid="false"])');
      const seconds =
        immediate || focus || invalid || env.hidden || env.immediate || env.themeOwned ? 0 : (clock.duration ?? 0);
      const old = ownership.current;
      // Flush suppressed cascade before restoring a clock, never an old target.
      if (old?.allowed && old.applied["transition-duration"] === "0s" && seconds > 0)
        node.ownerDocument.defaultView?.getComputedStyle(node).color;
      ownership.current = acquireFamily(
        node,
        {
          "transition-property": property,
          "transition-duration": `${seconds}s`,
          "transition-delay": "0s",
          "transition-timing-function": `cubic-bezier(${cm.scope.tokens.ease.out.join(",")})`,
        },
        "transition",
        old,
      );
      if (ownership.current.allowed) {
        if (seconds === 0 || (previousMode.current === "full" && mode !== "full")) cancelColors(node, owned);
        cancelUnsafeShadows(node, owned);
      }
      previousMode.current = mode;
    };
    const checkShadows = () => {
      if (ownership.current?.allowed) cancelUnsafeShadows(node, owned);
    };
    const focusIn = () => {
      focus = true;
      update(environment);
    };
    const focusOut = () => {
      focus = false;
      update(environment);
    };
    node.addEventListener("transitionrun", checkShadows);
    node.addEventListener("focusin", focusIn);
    node.addEventListener("focusout", focusOut);
    const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, update);
    const observer = new MutationObserver((records) => {
      if (
        records.some(
          (record) =>
            record.attributeName !== "style" ||
            familyStyle(record.oldValue, "transition") !== familyStyle(node.getAttribute("style"), "transition"),
        )
      )
        update(environment);
    });
    observer.observe(node, {
      attributes: true,
      attributeOldValue: true,
      attributeFilter: ["aria-invalid", "data-invalid", "class", "style"],
    });
    return (release = true) => {
      observer.disconnect();
      unsubscribe();
      node.removeEventListener("transitionrun", checkShadows);
      node.removeEventListener("focusin", focusIn);
      node.removeEventListener("focusout", focusOut);
      if (release) {
        releaseFamily(ownership.current);
        ownership.current = null;
      }
    };
  });
  committed(() => {
    if (owner.node.current && ownership.current?.allowed) cancelUnsafeShadows(owner.node.current, owned);
  });
  return bindings(
    {
      ref: owner.ref,
      "data-motion": cm.mode,
      "data-cadence-color": property,
      "data-cadence-scope": "",
      style: motionScopeStyle({ ...cm.inheritedScope, effectiveDurations: cm.scope.effectiveDurations }, cm.timeScale),
    },
    ownership,
  );
}

/** Theme-clock status only. Removing its shorthand restores current cascade paint. */
export function useContinuousMotion<T extends MotionElement>(
  externalRef: Ref<T> | undefined,
  cm: CadenceMotion,
  animation: "spin" | "pulse",
  active = true,
) {
  const ownership = useRef<FamilyOwner | null>(null);
  const signature = JSON.stringify([cm.mode, animation, active]);
  const owner = useCssConnection(externalRef, signature, (node) => {
    const view = node.ownerDocument.defaultView;
    if (!view) return () => {};
    let visible = false;
    let environment: MotionEnvironment;
    let opacityClasses: string | null | undefined;
    let inlineOpacity: string | undefined;
    let restingOpacity = 1;
    let themeOwned = false;
    const update = () => {
      // Framework pulse keyframes assume resting opacity one. Keep semantic
      // caller dimming static rather than replacing it with a brighter loop.
      const classes = node.getAttribute("class");
      if (
        animation === "pulse" &&
        (classes !== opacityClasses ||
          environment.themeOwned !== themeOwned ||
          (node.style.opacity === "" && inlineOpacity !== ""))
      ) {
        releaseFamily(ownership.current);
        ownership.current = null;
        restingOpacity = Number(view.getComputedStyle(node).opacity);
        opacityClasses = classes;
      }
      themeOwned = environment.themeOwned;
      inlineOpacity = node.style.opacity;
      const compatibleOpacity =
        animation !== "pulse" || (node.style.opacity === "" ? restingOpacity : Number(node.style.opacity)) === 1;
      const allowed =
        compatibleOpacity &&
        active &&
        visible &&
        cm.mode === "full" &&
        !environment.reduced &&
        !environment.hidden &&
        !environment.immediate;
      ownership.current = acquireFamily(
        node,
        { animation: allowed ? `var(--animate-${animation})` : "none" },
        "animation",
        ownership.current,
      );
    };
    const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (next) => {
      environment = next;
      update();
    });
    const rect = node.getBoundingClientRect();
    visible =
      rect.width > 0 &&
      rect.height > 0 &&
      rect.bottom > 0 &&
      rect.right > 0 &&
      rect.top < view.innerHeight &&
      rect.left < view.innerWidth;
    update();
    const observer = new IntersectionObserver((entries) => {
      const entry = entries.find((entry) => entry.target === node);
      if (entry) {
        visible = entry.isIntersecting && entry.intersectionRatio > 0;
        update();
      }
    });
    observer.observe(node);
    const changes = new MutationObserver((records) => {
      if (
        records.some(
          (record) =>
            record.attributeName !== "style" ||
            familyStyle(record.oldValue, "animation") !== familyStyle(node.getAttribute("style"), "animation"),
        )
      )
        update();
    });
    changes.observe(node, { attributes: true, attributeOldValue: true, attributeFilter: ["class", "style"] });
    return (release = true) => {
      observer.disconnect();
      changes.disconnect();
      unsubscribe();
      if (release) {
        releaseFamily(ownership.current);
        ownership.current = null;
      }
    };
  });
  return bindings(
    {
      ref: owner.ref,
      "data-motion": cm.mode,
      "data-cadence-loop": animation,
      "data-cadence-scope": "",
      style: motionScopeStyle({ ...cm.inheritedScope, effectiveDurations: cm.scope.effectiveDurations }, cm.timeScale),
    },
    ownership,
  );
}

/** Shared signals, scoped to a document. No animation discovery or global patches. */
export interface MotionEnvironment {
  hidden: boolean;
  immediate: boolean;
  reduced: boolean;
  themeOwned: boolean;
}

type Listener = (environment: MotionEnvironment) => void;
const documents = new WeakMap<
  Document,
  {
    listeners: Set<Listener>;
    read(): MotionEnvironment;
    notify(): void;
    dispose(): void;
    themeDepth: number;
  }
>();

function environment(doc: Document) {
  const existing = documents.get(doc);
  if (existing) return existing;
  const view = doc.defaultView;
  const queries = ["(prefers-reduced-motion: reduce)", "(forced-colors: active)", "print"].map((q) =>
    view?.matchMedia(q),
  );
  let suspended = false;
  let printing = false;
  const state = {
    listeners: new Set<Listener>(),
    themeDepth: 0,
    read: (): MotionEnvironment => ({
      hidden: suspended || doc.visibilityState === "hidden",
      immediate: printing || Boolean(queries[1]?.matches || queries[2]?.matches),
      reduced: Boolean(queries[0]?.matches),
      themeOwned: state.themeDepth > 0,
    }),
    notify: () => {
      for (const listener of state.listeners) listener(state.read());
    },
    dispose: () => {
      for (const query of queries) query?.removeEventListener("change", state.notify);
      doc.removeEventListener("visibilitychange", state.notify);
      view?.removeEventListener("pagehide", hide);
      view?.removeEventListener("pageshow", show);
      view?.removeEventListener("beforeprint", beforePrint);
      view?.removeEventListener("afterprint", afterPrint);
      documents.delete(doc);
    },
  };
  const hide = () => {
    suspended = true;
    state.notify();
  };
  const show = () => {
    suspended = false;
    state.notify();
  };
  const beforePrint = () => {
    printing = true;
    state.notify();
  };
  const afterPrint = () => {
    printing = false;
    state.notify();
  };
  for (const query of queries) query?.addEventListener("change", state.notify);
  doc.addEventListener("visibilitychange", state.notify);
  view?.addEventListener("pagehide", hide);
  view?.addEventListener("pageshow", show);
  view?.addEventListener("beforeprint", beforePrint);
  view?.addEventListener("afterprint", afterPrint);
  documents.set(doc, state);
  return state;
}

export function subscribeMotionEnvironment(doc: Document, listener: Listener) {
  const state = environment(doc);
  state.listeners.add(listener);
  listener(state.read());
  return () => {
    state.listeners.delete(listener);
    if (!state.listeners.size && !state.themeDepth) state.dispose();
  };
}

/** The theme owner commits synchronously; local colour owners fold that change. */
export function coordinateMotionTheme(doc: Document, commit: () => void) {
  const state = environment(doc);
  state.themeDepth++;
  state.notify();
  try {
    commit();
  } finally {
    state.themeDepth--;
    state.notify();
    if (!state.listeners.size && !state.themeDepth) state.dispose();
  }
}
